        boolean lock = false;
        try {
            lock = lockProvider.lock(lockConfig);
        } catch (Exception e) {
            LogUtils.error(log, this.getClass().getName() + " execute error. lockName:[{}]", lockName, e);
        }

        return lock;
    }

